DROP TABLE IF EXISTS import_contratos_enero_2026;
CREATE TABLE import_contratos_enero_2026 (
  id INT AUTO_INCREMENT PRIMARY KEY,
  id_contrato VARCHAR(50) NOT NULL,
  fecha_firma DATE NULL,
  dni VARCHAR(20) NULL,
